-- ===== MODULE: Modules/Other/infinite_zoom.lua (deobfuscated) =====
__CRYPTIC_MODULES['Modules/Other/infinite_zoom.lua'] = function(...)
-- [[ Cryptic Hub - Infinite Camera Zoom ]]
-- يسمح لك تبعد/تقرّب الكاميرا لأي مسافة بدون حدود
-- Localized via i18n. الكي: other.infinite_zoom.*

local i18n = getgenv().CrypticI18n
local T    = (i18n and i18n.T) or function(k) return k end

return function(Tab, UI)
    local Players     = game:GetService("Players")
    local StarterGui  = game:GetService("StarterGui")
    local RunService  = game:GetService("RunService")
    local lp          = Players.LocalPlayer

    local originalMin = lp.CameraMinZoomDistance
    local originalMax = lp.CameraMaxZoomDistance
    local enforceConn = nil

    local function Notify(text)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title    = "Cryptic Hub",
                Text     = text,
                Duration = 3,
            })
        end)
    end

    local function applyInfinite()
        pcall(function()
            lp.CameraMinZoomDistance = 0.5
            lp.CameraMaxZoomDistance = math.huge
        end)
    end

    local function restoreOriginal()
        pcall(function()
            lp.CameraMinZoomDistance = originalMin or 0.5
            lp.CameraMaxZoomDistance = originalMax or 400
        end)
    end

    Tab:AddToggle(T("other.infinite_zoom.label"), function(state)
        if state then
            applyInfinite()
            -- إعادة فرض القيم باستمرار في حال السيرفر حاول يرجعها
            if enforceConn then enforceConn:Disconnect() end
            enforceConn = RunService.Heartbeat:Connect(function()
                if lp.CameraMaxZoomDistance ~= math.huge or lp.CameraMinZoomDistance > 0.5 then
                    applyInfinite()
                end
            end)
            Notify(T("other.infinite_zoom.on"))
        else
            if enforceConn then enforceConn:Disconnect() enforceConn = nil end
            restoreOriginal()
            Notify(T("other.infinite_zoom.off"))
        end
    end)

    -- لو غير الشخصية أعد تطبيق القيم لو الميزة مفعلة
    lp.CharacterAdded:Connect(function()
        task.wait(0.5)
        if enforceConn then applyInfinite() end
    end)
end

end

-- ===== MODULE: Modules/Other/lol.lua (deobfuscated) =====
__CRYPTIC_MODULES['Modules/Other/lol.lua'] = function(...)
return function(Tab, UI)
    -- 1. كود الخط (يُوضع في البداية ليظهر في الأعلى)
    local TabOps = Tab.TabOps or {}
    
    if TabOps.Page then
        TabOps.Order = (TabOps.Order or 0) + 1
        local L = Instance.new("Frame", TabOps.Page)
        
        -- السر هنا: LayoutOrder = -1 يجعله فوق كل الأزرار الأخرى
        L.LayoutOrder = -1 
        
        L.Size = UDim2.new(0.95, 0, 0, 1)
        L.AnchorPoint = Vector2.new(0.5, 0)
        L.Position = UDim2.new(0.5, 0, 0, 0)
        L.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        L.BackgroundTransparency = 0.7
        L.BorderSizePixel = 0
        
        local G = Instance.new("UIGradient", L)
        G.Color = ColorSequence.new{
            ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 255, 150)), -- الأخضر في البداية
            ColorSequenceKeypoint.new(1, Color3.fromRGB(0, 150, 255))  -- الأزرق في النهاية
        }
    end

    -- 2. هنا تبدأ بإضافة الأزرار العادية (ستظهر تحت الخط تلقائياً)
    -- Tab:AddToggle(...)
    -- Tab:AddSlider(...)
end

end

-- ===== MODULE: Modules/Other/no_camera_clip.lua (deobfuscated) =====
__CRYPTIC_MODULES['Modules/Other/no_camera_clip.lua'] = function(...)
-- [[ Cryptic Hub - No Camera Clip (Camera passes through walls) ]]
-- يخلي الكاميرا ما تتصادم بالجدران، تشوف اللاعب من خلال أي شيء
-- Localized via i18n. الكي: other.no_camera_clip.*

local i18n = getgenv().CrypticI18n
local T    = (i18n and i18n.T) or function(k) return k end

return function(Tab, UI)
    local Players     = game:GetService("Players")
    local StarterGui  = game:GetService("StarterGui")
    local RunService  = game:GetService("RunService")
    local lp          = Players.LocalPlayer

    local originalOcclusion = lp.DevCameraOcclusionMode
    local enforceConn = nil

    local function Notify(text)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title    = "Cryptic Hub",
                Text     = text,
                Duration = 3,
            })
        end)
    end

    local function applyNoClip()
        pcall(function()
            lp.DevCameraOcclusionMode = Enum.DevCameraOcclusionMode.Invisicam
        end)
    end

    local function restoreOriginal()
        pcall(function()
            lp.DevCameraOcclusionMode = originalOcclusion or Enum.DevCameraOcclusionMode.Zoom
        end)
    end

    Tab:AddToggle(T("other.no_camera_clip.label"), function(state)
        if state then
            -- خزّن القيمة الأصلية الحالية كل مرة عشان لو فيه ميزة ثانية غيّرتها
            originalOcclusion = lp.DevCameraOcclusionMode
            applyNoClip()
            -- فرض دائم لو شيء حاول يرجعها
            if enforceConn then enforceConn:Disconnect() end
            enforceConn = RunService.Heartbeat:Connect(function()
                if lp.DevCameraOcclusionMode ~= Enum.DevCameraOcclusionMode.Invisicam then
                    applyNoClip()
                end
            end)
            Notify(T("other.no_camera_clip.on"))
        else
            if enforceConn then enforceConn:Disconnect() enforceConn = nil end
            restoreOriginal()
            Notify(T("other.no_camera_clip.off"))
        end
    end)

    -- إعادة تطبيق بعد الموت/الـ respawn
    lp.CharacterAdded:Connect(function()
        task.wait(0.5)
        if enforceConn then applyNoClip() end
    end)
end

end

-- ===== MODULE: Modules/Other/notepad.lua (deobfuscated) =====
__CRYPTIC_MODULES['Modules/Other/notepad.lua'] = function(...)
-- [[ Cryptic Hub – Misc v2: notepad (مذكرة متكاملة) ]]
-- المسار: Miscv2/notepad.lua
-- مفاتيح i18n: misc.notepad.*

return function(Tab, UI)
    local i18n = getgenv().CrypticI18n
    local T    = (i18n and i18n.T) or function(k) return k end
    local TweenService = game:GetService("TweenService")
    local StarterGui   = game:GetService("StarterGui")

    -- ── ثيم متوافق مع Cryptic Hub ─────────────────────────
    local ACCENT  = Color3.fromRGB(0, 255, 150)
    local ACCENT2 = Color3.fromRGB(0, 150, 255)
    local WARN    = Color3.fromRGB(255, 200, 60)
    local DANGER  = Color3.fromRGB(255, 80, 80)
    local BG_DEEP = Color3.fromRGB(10, 11, 16)
    local BG      = Color3.fromRGB(16, 17, 23)
    local BG2     = Color3.fromRGB(20, 22, 30)
    local TEXT    = Color3.fromRGB(228, 232, 245)
    local MUTED   = Color3.fromRGB(110, 115, 135)

    local FILE_BODY  = "CrypticHub_Notepad_body.txt"
    local FILE_TITLE = "CrypticHub_Notepad_title.txt"

    -- ── أدوات مساعدة ─────────────────────────────────────
    local function tw(obj, props, t)
        TweenService:Create(
            obj,
            TweenInfo.new(t or 0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            props
        ):Play()
    end

    local function Notify(txt)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = "📝 " .. T("misc.notepad.title"),
                Text  = txt,
                Duration = 2,
            })
        end)
    end

    local function GradStroke(parent, thick, trans)
        local s = Instance.new("UIStroke", parent)
        s.Thickness    = thick  or 1.2
        s.Transparency = trans  or 0.45
        local g = Instance.new("UIGradient", s)
