                local okT, title = pcall(readfile, FILE_TITLE)
                if okB and type(body)  == "string" and body  ~= "" then NoteBox.Text  = body  end
                if okT and type(title) == "string" and title ~= "" then TitleBox.Text = title end
            end
        end)
    end)
