__CRYPTIC_MODULES['UI/Elements/LockedToggle.lua'] = function(...)
-- [[ Cryptic Hub - Element: LockedToggle ]]
-- توغل مع قفل ذكي — يُقفل مع سبب ويُفتح تلقائياً عند استيفاء الشرط

return function(TabOps, label, reason, callback)
    local TweenService = game:GetService("TweenService")
    local function Tw(obj, props, t)
        TweenService:Create(obj, TweenInfo.new(t or 0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props):Play()
    end

    TabOps.Order = TabOps.Order + 1

    local ACCENT    = Color3.fromRGB(0, 255, 150)
    local ACCENT2   = Color3.fromRGB(0, 150, 255)
    local OFF_CLR   = Color3.fromRGB(45, 45, 55)
    local LOCK_CLR  = Color3.fromRGB(80, 80, 95)

    local H_COMPACT = 46   -- ارتفاع لما مفتوح (نفس Toggle عادي)
    local H_LOCKED  = 64   -- ارتفاع لما مقفول (مكان لنص السبب)

    -- ── الإطار الخارجي ──────────────────────────────────────
    local R = Instance.new("Frame", TabOps.Page)
    R.LayoutOrder             = TabOps.Order
    R.Size                    = UDim2.new(0.98, 0, 0, H_COMPACT)
    R.BackgroundColor3        = Color3.fromRGB(16, 16, 20)
    R.BackgroundTransparency  = 0.1
    R.ClipsDescendants        = true
    Instance.new("UICorner", R).CornerRadius = UDim.new(0, 10)

    local Stroke = Instance.new("UIStroke", R)
    Stroke.Thickness    = 1.2
    Stroke.Transparency = 0.55
    local Grad = Instance.new("UIGradient", Stroke)
    Grad.Color    = ColorSequence.new{
        ColorSequenceKeypoint.new(0, ACCENT),
        ColorSequenceKeypoint.new(1, ACCENT2)
    }
    Grad.Rotation = 45

    -- ── الاسم ─────────────────────────────────────────────
    local Lbl = Instance.new("TextLabel", R)
    Lbl.Text                   = label
    Lbl.Size                   = UDim2.new(1, -65, 0, 22)
    Lbl.Position               = UDim2.new(0, 10, 0, 12)
    Lbl.TextColor3             = Color3.fromRGB(210, 210, 225)
    Lbl.BackgroundTransparency = 1
    Lbl.TextXAlignment         = Enum.TextXAlignment.Left
    Lbl.Font                   = Enum.Font.GothamSemibold
    Lbl.TextSize               = 11
    Lbl.TextWrapped            = false

    -- ── سبب القفل (مخفي افتراضياً، يظهر لما مقفول) ────────
    local ReasonLbl = Instance.new("TextLabel", R)
    ReasonLbl.Text                   = "🔒 " .. (reason or "")
    ReasonLbl.Size                   = UDim2.new(1, -20, 0, 16)
    ReasonLbl.Position               = UDim2.new(0, 10, 0, H_COMPACT - 2)
    ReasonLbl.TextColor3             = Color3.fromRGB(180, 130, 80)
    ReasonLbl.BackgroundTransparency = 1
    ReasonLbl.TextXAlignment         = Enum.TextXAlignment.Left
    ReasonLbl.Font                   = Enum.Font.Gotham
    ReasonLbl.TextSize               = 9
    ReasonLbl.TextWrapped            = true
    ReasonLbl.TextTransparency       = 1   -- شفاف في البداية

    -- ── شريط التوغل ───────────────────────────────────────
    local Track = Instance.new("Frame", R)
    Track.Size             = UDim2.new(0, 44, 0, 22)
    Track.Position         = UDim2.new(1, -54, 0, 12)
    Track.BackgroundColor3 = OFF_CLR
    Track.BorderSizePixel  = 0
    Instance.new("UICorner", Track).CornerRadius = UDim.new(1, 0)

    local Knob = Instance.new("Frame", Track)
    Knob.Size             = UDim2.new(0, 16, 0, 16)
    Knob.Position         = UDim2.new(0, 3, 0.5, -8)
    Knob.BackgroundColor3 = Color3.fromRGB(200, 200, 215)
    Knob.BorderSizePixel  = 0
    Instance.new("UICorner", Knob).CornerRadius = UDim.new(1, 0)

    -- ── زر الضغط الشفاف ────────────────────────────────────
    local B = Instance.new("TextButton", R)
    B.Size                   = UDim2.new(1, 0, 1, 0)
    B.BackgroundTransparency = 1
    B.Text                   = ""
    B.AutoButtonColor        = false

    -- ── الحالة ─────────────────────────────────────────────
    local isActive = false
    local isLocked = false
    local configKey = TabOps.TabName .. "_" .. label

    if TabOps.UI.ConfigData[configKey] ~= nil then
        isActive = TabOps.UI.ConfigData[configKey]
    end

    -- ── تحديث مظهر التوغل ──────────────────────────────────
    local function refreshVisual()
        if isLocked then
            -- مقفول: كبّر الإطار، أظهر السبب
            Tw(R,      {Size = UDim2.new(0.98, 0, 0, H_LOCKED)}, 0.2)
            Tw(Track,  {BackgroundColor3 = LOCK_CLR}, 0.18)
            Tw(Knob,   {Position = UDim2.new(0, 3, 0.5, -8), BackgroundColor3 = Color3.fromRGB(120, 120, 135)}, 0.18)
            Tw(Stroke, {Transparency = 0.7}, 0.18)
            Tw(ReasonLbl, {TextTransparency = 0}, 0.25)
            Lbl.TextColor3 = Color3.fromRGB(130, 130, 145)
        else
            -- مفتوح: صغّر الإطار، أخفِ السبب
            Tw(R,      {Size = UDim2.new(0.98, 0, 0, H_COMPACT)}, 0.2)
            Tw(ReasonLbl, {TextTransparency = 1}, 0.12)
            Lbl.TextColor3 = Color3.fromRGB(210, 210, 225)
            if isActive then
                Tw(Track,  {BackgroundColor3 = ACCENT}, 0.18)
                Tw(Knob,   {Position = UDim2.new(0, 25, 0.5, -8), BackgroundColor3 = Color3.fromRGB(255, 255, 255)}, 0.18)
                Tw(Stroke, {Transparency = 0.1}, 0.18)
            else
                Tw(Track,  {BackgroundColor3 = OFF_CLR}, 0.18)
                Tw(Knob,   {Position = UDim2.new(0, 3, 0.5, -8), BackgroundColor3 = Color3.fromRGB(200, 200, 215)}, 0.18)
                Tw(Stroke, {Transparency = 0.55}, 0.18)
            end
        end
    end

    -- ── setState: بدون guard — الكود الداخلي يقدر يطفيه دايمًا ──
    -- الضغط اليدوي من المستخدم يُمنع في MouseButton1Click
    local function setState(state, isClick)
        -- لو مقفول: السماح فقط بالإطفاء الداخلي (false)، مش التشغيل
        if isLocked and state then return end
        isActive = state
        TabOps.UI.ConfigData[configKey] = isActive
        refreshVisual()
        pcall(callback, isActive)
        if isClick and TabOps.LogAction then
            TabOps.LogAction("⚙️ تفعيل/إيقاف ميزة", label,
                isActive and "مفعل ✅" or "معطل ❌",
                isActive and 5763719 or 15548997)
        end
    end

    -- ── Hover ───────────────────────────────────────────────
    B.MouseEnter:Connect(function()
        if not isLocked then Tw(R, {BackgroundTransparency = 0}, 0.12) end
    end)
    B.MouseLeave:Connect(function()
        Tw(R, {BackgroundTransparency = 0.1}, 0.12)
    end)

    B.MouseButton1Click:Connect(function()
        if isLocked then return end   -- المستخدم ممنوع لما مقفول
        setState(not isActive, true)
    end)

    -- ── تطبيق الحالة المحفوظة عند البدء ────────────────────
    if isActive then
        Track.BackgroundColor3 = ACCENT
        Knob.Position          = UDim2.new(0, 25, 0.5, -8)
        Knob.BackgroundColor3  = Color3.fromRGB(255, 255, 255)
        Stroke.Transparency    = 0.1
        task.spawn(function() task.wait(1.5); pcall(callback, isActive) end)
    end

    -- ── الكائن المُعاد ─────────────────────────────────────
    return {
        -- إيقاف/تشغيل برمجي — يقدر يطفي حتى لو مقفول
        SetState = function(self, state)
            setState(state, false)
        end,

        -- قفل/فتح التوغل مع تحريك الحجم
        SetLocked = function(self, locked)
            if isLocked == locked then return end
            isLocked = locked
            if isLocked and isActive then
                -- أوقف التشغيل لو كان مفعلاً
                isActive = false
                TabOps.UI.ConfigData[configKey] = false
                pcall(callback, false)
            end
            refreshVisual()
        end,
    }
end

end

