M._Translations = Translations

-- ============================================================
-- الحالة الداخلية + التحميل/الحفظ
-- ============================================================
local current = "ar"

function M.Load()
    -- Arabic-only build: always start in Arabic.
    current = "ar"
    return true
end

function M.Save(code)
    pcall(function()
        if writefile then
            writefile(FILE_NAME, HttpService:JSONEncode({ code = code }))
        end
    end)
end

function M.HasSaved()
    -- Arabic-only build: do not open the language picker.
    return true
end

function M.Set(code)
    if code ~= "ar" then return false end
    current = "ar"
    M.Save("ar")
    return true
end

function M.Get()        return current end
function M.GetMeta()    return M.Languages[current] end
function M.GetAll()     return M.Languages end

-- ============================================================
-- T(key) → النص بلغة المستخدم، أو fallback إلى الإنجليزية، أو المفتاح نفسه
-- ============================================================
function M.T(key)
    local t = Translations.ar
    if t and t[key] ~= nil then return t[key] end
    return key
end

-- T(key, lang) → بلغة محددة (للاستخدام في معاينة)
function M.TIn(key, lang)
    return M.T(key)
end

-- إضافة/تجاوز ترجمات وقت التشغيل (للموديولات اللي تبي تسجل ترجماتها)
function M.Register(code, table_)
    if not Translations[code] then Translations[code] = {} end
    for k, v in pairs(table_) do
        Translations[code][k] = v
    end
end

return M

end

-- ===== MAIN: Cryptic Hub =====
local function Import(path)
    local factory = __CRYPTIC_MODULES[path]
    if not factory then warn("Cryptic bundle: missing module " .. tostring(path)); return nil end
    local ok, result = pcall(factory)
    if not ok then warn("Cryptic bundle: module error " .. tostring(path) .. ": " .. tostring(result)); return nil end
    return result
end

